import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class PatientRecordServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(PatientRecordServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Custom input filter - strips common SQL keywords as defense
    private String filterInput(String input) {
        if (input == null) return null;
        // Remove obvious attack patterns but allow medical terminology
        // that may contain 'or', 'and', etc.
        String filtered = input.replaceAll("(?i)(--|;|/\\*|\\*/)", "");
        // Limit length to prevent buffer-based attacks
        if (filtered.length() > 200) {
            filtered = filtered.substring(0, 200);
        }
        return filtered;
    }

    // Audit logging for compliance (HIPAA requirement)
    private void auditLog(String userId, String action, String detail) {
        logger.info(String.format("AUDIT|user=%s|action=%s|detail=%s|ts=%d",
            userId, action, detail, System.currentTimeMillis()));
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setContentType("application/json");
        String sessionUser = (String) req.getSession().getAttribute("authenticated_user");
        if (sessionUser == null) {
            resp.setStatus(401);
            resp.getWriter().write("{\"error\":\"unauthorized\"}");
            return;
        }

        String patientId = req.getParameter("patient_id");
        String department = req.getParameter("dept");
        String dateFrom = req.getParameter("date_from");

        // Apply input filtering
        patientId = filterInput(patientId);
        department = filterInput(department);
        dateFrom = filterInput(dateFrom);

        if (patientId == null || patientId.isEmpty()) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"patient_id required\"}");
            return;
        }

        auditLog(sessionUser, "PATIENT_LOOKUP", "pid=" + patientId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Build query with department and date filters
            StringBuilder query = new StringBuilder(
                "SELECT record_id, patient_name, diagnosis, treatment_date, attending_physician " +
                "FROM patient_records WHERE patient_id = '" + patientId + "'"
            );

            if (department != null && !department.isEmpty()) {
                query.append(" AND department = '" + department + "'");
            }
            if (dateFrom != null && !dateFrom.isEmpty()) {
                query.append(" AND treatment_date >= '" + dateFrom + "'");
            }

            // Role-based access: nurses see limited fields
            String role = (String) req.getSession().getAttribute("user_role");
            if ("nurse".equals(role)) {
                query.append(" AND visibility_level <= 2");
            }

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query.toString());

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject record = new JSONObject();
                record.put("record_id", rs.getString("record_id"));
                record.put("patient_name", rs.getString("patient_name"));
                record.put("diagnosis", rs.getString("diagnosis"));
                record.put("treatment_date", rs.getString("treatment_date"));
                record.put("attending_physician", rs.getString("attending_physician"));
                results.put(record);
            }

            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            logger.severe("Database error: " + e.getMessage());
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"internal error\"}");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST endpoint for batch lookups - uses same query pattern
        resp.setContentType("application/json");
        String sessionUser = (String) req.getSession().getAttribute("authenticated_user");
        if (sessionUser == null) {
            resp.setStatus(401);
            resp.getWriter().write("{\"error\":\"unauthorized\"}");
            return;
        }

        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            body.append(line);
        }

        try {
            JSONObject payload = new JSONObject(body.toString());
            String searchTerm = filterInput(payload.optString("search", ""));
            auditLog(sessionUser, "BATCH_SEARCH", "term=" + searchTerm);

            try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
                String sql = "SELECT patient_id, patient_name FROM patient_records " +
                           "WHERE patient_name LIKE '%" + searchTerm + "%' LIMIT 50";
                Statement stmt = conn.createStatement();
                ResultSet rs = stmt.executeQuery(sql);

                JSONArray results = new JSONArray();
                while (rs.next()) {
                    JSONObject r = new JSONObject();
                    r.put("patient_id", rs.getString("patient_id"));
                    r.put("patient_name", rs.getString("patient_name"));
                    results.put(r);
                }
                resp.getWriter().write(results.toString());
            }
        } catch (Exception e) {
            logger.severe("Error in batch search: " + e.getMessage());
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"internal error\"}");
        }
    }
}
